import datetime
from typing import Optional
from sqlalchemy import String, Float, Enum as SQLEnum, Text, ForeignKey, JSON, Integer, DateTime
from sqlalchemy.orm import Mapped, mapped_column, relationship
from backend.core.database import Base, TimestampMixin
from backend.models.enums import RecommendationType


class AnalysisReport(Base, TimestampMixin):
    """Synthesized risk report generated by the ClauseGuard analysis engine for a claim."""

    __tablename__ = "analysis_reports"

    claim_id: Mapped[int] = mapped_column(ForeignKey("claims.id", ondelete="CASCADE"), nullable=False, index=True)
    overall_risk_score: Mapped[float] = mapped_column(Float, nullable=False)  # 0.0 to 100.0
    recommendation: Mapped[RecommendationType] = mapped_column(
        SQLEnum(RecommendationType), nullable=False
    )
    confidence_score: Mapped[float] = mapped_column(Float, default=1.0)  # 0.0 to 1.0
    executive_summary: Mapped[str] = mapped_column(Text, nullable=False)
    findings_count: Mapped[int] = mapped_column(Integer, default=0)
    loophole_analysis: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    agent_trace: Mapped[Optional[dict]] = mapped_column(JSON, default=dict)  # Logs of LangGraph steps, decisions

    # Relationships
    claim: Mapped["backend.models.claim.Claim"] = relationship("backend.models.claim.Claim", back_populates="reports")

    def __repr__(self) -> str:
        return f"<AnalysisReport(id={self.id}, claim_id={self.claim_id}, score={self.overall_risk_score})>"


class AuditLog(Base):
    """System-wide immutable audit trail of actions taken by users or background agents."""

    __tablename__ = "audit_logs"

    id: Mapped[int] = mapped_column(Integer, primary_key=True, index=True, autoincrement=True)
    entity_type: Mapped[str] = mapped_column(String(50), nullable=False, index=True)  # policy, claim, doc, analysis
    entity_id: Mapped[str] = mapped_column(String(100), nullable=False, index=True)
    action: Mapped[str] = mapped_column(String(100), nullable=False)  # created, updated, analyzed, verified
    details: Mapped[Optional[str]] = mapped_column(Text, nullable=True)
    created_at: Mapped[datetime.datetime] = mapped_column(
        DateTime, default=lambda: datetime.datetime.now(datetime.timezone.utc), nullable=False
    )

    def __repr__(self) -> str:
        return f"<AuditLog(entity='{self.entity_type}:{self.entity_id}', action='{self.action}')>"
